-- 3. extrapolated_cells (country-level fallback)
UPDATE extrapolated_cells
SET cost_stack = jsonb_build_object(
  'rent_occupancy',         ROUND(predicted_rev_per_firm * 0.14),
  'payroll_total',          ROUND(predicted_rev_per_firm * 0.42),
  'cost_of_goods_sold',     ROUND(predicted_rev_per_firm * 0.06),
  'utilities',              ROUND(predicted_rev_per_firm * 0.03),
  'marketing_acquisition',  ROUND(predicted_rev_per_firm * 0.02),
  'insurance_professional', ROUND(predicted_rev_per_firm * 0.03),
  'equipment_maintenance',  ROUND(predicted_rev_per_firm * 0.02),
  'regulatory_licensing',   ROUND(predicted_rev_per_firm * 0.02),
  'refreshed_at',           '2026-05-24',
  'source_note',            'Barbershop industry benchmarks 2024 (Booksy, Bookedin). Country-level extrapolation; coarser than regional_cells.',
  'grade',                  'D'
)
WHERE industry_id = 'barbershops'
  AND predicted_rev_per_firm IS NOT NULL
  AND predicted_rev_per_firm > 0
  AND (cost_stack IS NULL OR cost_stack->>'grade' IN ('C', 'D'));
